{"command":"python3 - <<'PY'
import pathlib,tarfile,hashlib,subprocess
root=pathlib.Path.cwd()
for app in ['customer','customer-service']:
    original=root/'apps'/app/'out'
    expected={str(p.relative_to(original)):hashlib.sha256(p.read_bytes()).hexdigest() for p in original.rglob('*') if p.is_file()}
    with tarfile.open(root/'.sites/deploy05-artifacts'/f'{app}.tar.gz') as tf:
        got={m.name.removeprefix('./')[5:]:hashlib.sha256(tf.extractfile(m).read()).hexdigest() for m in tf.getmembers() if m.isfile() and m.name.removeprefix('./').startswith('dist/') and not m.name.removeprefix('./').startswith('dist/.openai/')}
    assert got==expected,app+' archive mismatch'
    assert any(b'https://variety-configuration-applications-refine.trycloudflare.com/' in p.read_bytes() for p in original.rglob('*.js'))
    checkout=root/'.sites'/('deploy05-save-'+app)
    for folder in ['apps/customer','apps/customer-service','packages','scripts/sites']:
        for file in subprocess.check_output(['git','ls-tree','-r','--name-only','4b6a4aa','--',folder],text=True).splitlines():
            if '/.openai/' not in file: assert (checkout/file).read_bytes()==subprocess.check_output(['git','show','4b6a4aa:'+file]),file
    print(app+': all '+str(len(got))+' built files match archive; API URL present; source matches 4b6a4aa.')
PY"}
